import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"Back up and restore","description":"Back up a Wake installation with wake-server backup, back up on a schedule, restore a backup and move Wake to another machine.","frontmatter":{"description":"Back up a Wake installation with wake-server backup, back up on a schedule, restore a backup and move Wake to another machine."},"headers":[],"relativePath":"run/backup.md","filePath":"run/backup.md","lastUpdated":1794486787000}'),r={name:"run/backup.md"};function n(i,e,d,c,p,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="back-up-and-restore" tabindex="-1">Back up and restore <a class="header-anchor" href="#back-up-and-restore" aria-label="Permalink to &quot;Back up and restore&quot;">​</a></h1><h2 id="back-up" tabindex="-1">Back up <a class="header-anchor" href="#back-up" aria-label="Permalink to &quot;Back up&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span></code></pre></div><p>It writes one file, <code>backups/wake-&lt;version&gt;-&lt;UTC time&gt;.tar</code> in the installation&#39;s directory (directory mode <code>0700</code>, file mode <code>0600</code>), and prints one line with its path and size:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Backup written: /home/you/wake-server/backups/wake-2.4.0-20261102T215053Z.tar (589 MiB)</span></span></code></pre></div><p>Wake keeps serving while it runs. Every upgrade and every restore writes a backup first.</p><h3 id="free-disk-first" tabindex="-1">Free disk first <a class="header-anchor" href="#free-disk-first" aria-label="Permalink to &quot;Free disk first&quot;">​</a></h3><p>Before a backup writes anything, <code>wake-server</code> checks the disk that holds <code>backups/</code>: it needs about the database&#39;s size plus twice the evidence files&#39; size free, for the copy and its file. With less, the backup, an upgrade (including the daily one) or a restore stops before it changes anything, and Wake keeps running:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wake-server: not enough free disk for the backup: it needs about 300 MB in /home/you/wake-server/backups, 200 MB are free</span></span></code></pre></div><p>Free space on that disk, for example by copying older backups elsewhere and deleting them from <code>backups/</code>, then run the command again. When a size cannot be read, the backup runs without the check.</p><p>Copy backups off the machine. A healthy upgrade removes the older upgrade backups (see <a href="/wake-dist/docs/run/upgrade#upgrade-backups-kept">Upgrade backups kept</a>); <code>wake-server</code> never deletes any other backup, so remove the ones you no longer need yourself.</p><h2 id="back-up-on-a-schedule" tabindex="-1">Back up on a schedule <a class="header-anchor" href="#back-up-on-a-schedule" aria-label="Permalink to &quot;Back up on a schedule&quot;">​</a></h2><p>Wake takes no backup by itself other than the one before each upgrade. To take one every night, run <code>crontab -e</code> as the user who installed Wake and add a line such as this one, which backs up at 03:30, machine time, and appends the output to a log. Write your installation directory in place of <code>/home/you/wake-server</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>30 3 * * * PATH=/usr/local/bin:/usr/bin:/bin /home/you/wake-server/wake-server backup &gt;&gt;/home/you/wake-server/backup.log 2&gt;&amp;1</span></span></code></pre></div><p><code>PATH</code> lets cron find <code>docker</code>; if <code>command -v docker</code> names another directory, add it. Then copy the new backups off the machine, for example with your usual backup tool or <code>rsync</code>.</p><p>A backup holds:</p><table tabindex="0"><thead><tr><th>Member</th><th>Contents</th></tr></thead><tbody><tr><td><code>manifest</code></td><td>The backup&#39;s format, the Wake version it was taken from, its time and what wrote it: <code>trigger=upgrade</code>, <code>backup</code> or <code>restore</code></td></tr><tr><td><code>postgres.sql.gz</code></td><td>The database: accounts, workspaces, tokens and every project&#39;s events</td></tr><tr><td><code>evidence/</code></td><td>Every evidence file</td></tr><tr><td><code>env</code></td><td>A copy of <code>.env</code>, with the installation&#39;s secrets: keep backups as private as <code>.env</code></td></tr></tbody></table><h2 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h2><p>A restore <strong>replaces the database and the evidence files</strong> with the backup&#39;s. Name the backup by its full path, or by a path relative to the directory you are in:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> installation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/backups/wake-2.4.0-20261102T215053Z.tar</span></span></code></pre></div><p>It stops Wake, writes a backup of the current data, replaces the database and the evidence files with the backup&#39;s, starts Wake and prints <code>Restored &lt;backup&gt; (Wake &lt;version&gt;). The data it replaced is in &lt;new backup&gt;</code>. Restoring that new backup undoes the restore.</p><p>It keeps <code>.env</code>, so the installation keeps its address and secrets, and the backup&#39;s accounts sign in.</p><p>A backup from a newer Wake is refused, naming the <code>wake-server upgrade --version</code> to run first: the server migrates an older database forward on start, but an older server cannot run a newer one. A missing file, one that is not a Wake backup (a backup compressed again, such as a <code>.tar.gz</code>: decompress it first) or one whose database dump is damaged is refused with nothing changed. A backup keeps working under another name.</p><p><code>wake-server restore</code> also reads a database dump named <code>wake-&lt;version&gt;-&lt;UTC time&gt;.sql.gz</code>, which holds the database only: it restores the database and keeps the evidence files.</p><h2 id="move-to-another-machine" tabindex="-1">Move to another machine <a class="header-anchor" href="#move-to-another-machine" aria-label="Permalink to &quot;Move to another machine&quot;">​</a></h2><p>Install the same release or a newer one on the new machine, copy the backup into its <code>backups/</code> and restore it there. The backup&#39;s <code>env</code> member holds the old installation&#39;s settings: carry over by hand the ones you set yourself, such as <a href="/wake-dist/docs/run/sign-in-providers">sign-in providers</a>, into the new <code>.env</code>.</p><p>To move a deployment you run yourself onto an installation, see <a href="/wake-dist/docs/run/images#move-onto-an-installation">Run the images yourself</a>.</p>',27)])])}const u=a(r,[["render",n]]);export{k as __pageData,u as default};
